findings.fix:
resource "google_compute_region_network_firewall_policy_association" "main" {
  name              = "${var.name}-regional-association"
  region            = var.region
  attachment_target = var.network
  firewall_policy   = google_compute_region_network_firewall_policy.main.name
}

output "network_policy_name" {
  value       = google_compute_network_firewall_policy.main.name
  description = "Name of the global network firewall policy, for attaching additional rules"
}

output "region_policy_name" {
  value       = google_compute_region_network_firewall_policy.main.name
  description = "Name of the regional network firewall policy, for attaching additional rules"
}

output "hierarchical_policy_name" {
  value       = try(google_compute_firewall_policy.hierarchical[0].name, null)
  description = "Generated name of the hierarchical firewall policy, null when var.parent is unset"
}
